  "inlineSchema": "// Hive — Community Operating System\n// Prisma Schema v1.0 (Phase 2)\n// Database: PostgreSQL via Supabase\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─── Enums ────────────────────────────────────────────────────────────────────\n\nenum UserRole {\n  MEMBER\n  ORGANIZER\n  ADMIN\n}\n\nenum EventStatus {\n  DRAFT\n  PENDING\n  PUBLISHED\n  REJECTED\n  COMPLETED\n}\n\nenum RsvpStatus {\n  APPROVED\n  WAITLISTED\n  CANCELLED\n  ATTENDED\n}\n\nenum AttendanceStatus {\n  PRESENT\n  ABSENT\n  LATE\n}\n\nenum MembershipStatus {\n  ACTIVE\n  INACTIVE\n  BANNED\n}\n\nenum OpportunityType {\n  HACKATHON\n  INTERNSHIP\n  OPEN_SOURCE\n  VOLUNTEER\n}\n\nenum BadgeTier {\n  BRONZE\n  SILVER\n  GOLD\n  PLATINUM\n}\n\n// ─── Core Models ──────────────────────────────────────────────────────────────\n\n/// Maps 1:1 to the Supabase Auth user. Stores app-level profile data.\nmodel User {\n  id        String   @id @default(uuid())\n  /// Must match auth.users.id in Supabase\n  authId    String   @unique\n  email     String   @unique\n  fullName  String\n  username  String   @unique\n  avatarUrl String?\n  bio       String?\n  role      UserRole @default(MEMBER)\n\n  // Social links\n  githubUrl    String?\n  linkedinUrl  String?\n  portfolioUrl String?\n\n  // Skills & Interests (stored as arrays for simplicity at MVP scale)\n  skills    String[] @default([])\n  interests String[] @default([])\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  memberships       Membership[]\n  createdEvents     Event[]          @relation(\"EventOrganizer\")\n  registrations     Registration[]\n  attendanceRecords Attendance[]\n  communityScores   CommunityScore[]\n  earnedBadges      UserBadge[]\n  announcements     Announcement[]\n\n  @@index([authId])\n  @@index([username])\n  @@map(\"users\")\n}\n\n/// A developer community (e.g. \"Google Developer Groups – Campus\")\nmodel Community {\n  id          String  @id @default(uuid())\n  name        String\n  slug        String  @unique\n  description String?\n  logoUrl     String?\n  bannerUrl   String?\n  website     String?\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  memberships   Membership[]\n  events        Event[]\n  announcements Announcement[]\n  scores        CommunityScore[]\n\n  @@index([slug])\n  @@map(\"communities\")\n}\n\n/// Join table: User ↔ Community with role context\nmodel Membership {\n  id          String           @id @default(uuid())\n  userId      String\n  communityId String\n  role        UserRole         @default(MEMBER)\n  status      MembershipStatus @default(ACTIVE)\n  joinedAt    DateTime         @default(now())\n  updatedAt   DateTime         @updatedAt\n\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  community Community @relation(fields: [communityId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, communityId])\n  @@index([communityId])\n  @@map(\"memberships\")\n}\n\n// ─── Events ───────────────────────────────────────────────────────────────────\n\nmodel Event {\n  id          String  @id @default(uuid())\n  communityId String?\n  organizerId String\n  title       String\n  slug        String  @unique\n  description String?\n  coverUrl    String?\n  location    String?\n  isOnline    Boolean @default(false)\n  meetLink    String?\n\n  status          EventStatus @default(DRAFT)\n  startAt         DateTime\n  endAt           DateTime\n  capacity        Int?\n  rejectionReason String?\n  // QR code token for attendance scanning\n  qrToken         String      @unique @default(uuid())\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  community     Community?     @relation(fields: [communityId], references: [id], onDelete: Cascade)\n  organizer     User?          @relation(\"EventOrganizer\", fields: [organizerId], references: [id])\n  registrations Registration[]\n  attendance    Attendance[]\n\n  @@index([communityId])\n  @@index([status])\n  @@index([startAt])\n  @@map(\"events\")\n}\n\n/// Member signs up for an event\nmodel Registration {\n  id      String     @id @default(uuid())\n  userId  String\n  eventId String\n  status  RsvpStatus @default(APPROVED)\n\n  registeredAt DateTime  @default(now())\n  cancelledAt  DateTime?\n\n  user  User  @relation(fields: [userId], references: [id], onDelete: Cascade)\n  event Event @relation(fields: [eventId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, eventId])\n  @@index([eventId])\n  @@map(\"registrations\")\n}\n\n/// Attendance record after QR scan at the event door\nmodel Attendance {\n  id        String           @id @default(uuid())\n  userId    String\n  eventId   String\n  status    AttendanceStatus @default(PRESENT)\n  scannedAt DateTime         @default(now())\n\n  user  User  @relation(fields: [userId], references: [id], onDelete: Cascade)\n  event Event @relation(fields: [eventId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, eventId])\n  @@index([eventId])\n  @@map(\"attendance\")\n}\n\n// ─── Community Score Engine ────────────────────────────────────────────────────\n\n/// Point log for the community score engine\nmodel CommunityScore {\n  id          String  @id @default(uuid())\n  userId      String\n  communityId String\n  action      String // e.g. \"ATTEND_EVENT\", \"HOST_SESSION\", etc.\n  points      Int\n  refId       String? // Optional reference ID (eventId, opportunityId, etc.)\n  note        String?\n\n  createdAt DateTime @default(now())\n\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  community Community @relation(fields: [communityId], references: [id], onDelete: Cascade)\n\n  @@index([userId, communityId])\n  @@map(\"community_scores\")\n}\n\n// ─── Gamification ─────────────────────────────────────────────────────────────\n\nmodel Badge {\n  id          String    @id @default(uuid())\n  name        String    @unique\n  description String\n  iconUrl     String?\n  tier        BadgeTier @default(BRONZE)\n  pointValue  Int       @default(0)\n\n  createdAt DateTime    @default(now())\n  earnedBy  UserBadge[]\n\n  @@map(\"badges\")\n}\n\nmodel UserBadge {\n  id       String   @id @default(uuid())\n  userId   String\n  badgeId  String\n  earnedAt DateTime @default(now())\n\n  user  User  @relation(fields: [userId], references: [id], onDelete: Cascade)\n  badge Badge @relation(fields: [badgeId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, badgeId])\n  @@index([userId])\n  @@map(\"user_badges\")\n}\n\n// ─── Community Content ────────────────────────────────────────────────────────\n\nmodel Announcement {\n  id          String  @id @default(uuid())\n  communityId String\n  authorId    String\n  title       String\n  content     String\n  isPinned    Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  community Community @relation(fields: [communityId], references: [id], onDelete: Cascade)\n  author    User      @relation(fields: [authorId], references: [id])\n\n  @@index([communityId])\n  @@map(\"announcements\")\n}\n",
